// Scope decides which variables a line can see
var globalVar = "global";          // top-level scope
function demo() {
  var fnVar = "function-scoped";   // visible in the whole function
  if (true) {
    let blockLet = "block-scoped"; // visible only inside { }
    var leaky = "var ignores blocks";
    console.log("inside block:", globalVar, fnVar, blockLet);
  }
  console.log("after block:", leaky);
  console.log("blockLet visible?", typeof blockLet); // not defined here
}
demo();
