// A long-lived owner holding closures keeps their captured data alive
const listeners = [];                 // long-lived "emitter"
function subscribe(id) {
  const big = new Array(1000).fill(id);   // captured data
  const handler = () => big.length;       // closure keeps 'big' reachable
  listeners.push(handler);
  return () => {                          // unsubscribe removes the reference
    const i = listeners.indexOf(handler);
    if (i >= 0) listeners.splice(i, 1);
  };
}
const unsubs = [];
for (let i = 0; i < 5; i++) unsubs.push(subscribe(i));
console.log("listeners after subscribing:", listeners.length);
// Leak: forgetting to unsubscribe, so all 5 closures (and arrays) stay alive
// Fix: unsubscribe when the owner goes away
unsubs.forEach(u => u());
console.log("listeners after cleanup:", listeners.length);
// Bounded cache: evict the oldest key so it cannot grow forever
const cache = new Map();
function put(k, v, max = 3) {
  cache.set(k, v);
  if (cache.size > max) cache.delete(cache.keys().next().value);
}
for (let i = 0; i < 6; i++) put("k" + i, i);
console.log("bounded cache keys:", [...cache.keys()].join(","));

let calls = 0;
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    // single primitive arg: use it directly, otherwise serialise
    const key = args.length === 1 ? args[0] : JSON.stringify(args);
    if (!cache.has(key)) cache.set(key, fn.apply(this, args)); // has(), not truthiness
    return cache.get(key);
  };
}
const slowSquare = n => { calls++; return n * n; };
const fastSquare = memoize(slowSquare);
console.log("results:", [4, 4, 5, 4, 5, 0, 0].map(fastSquare).join(","));
console.log("real calls:", calls, "(7 requests)");
// Pitfall: a falsy result must still be cached
calls = 0;
fastSquare(0); fastSquare(0);
console.log("calls for 0 after warm cache:", calls);
// Recursive memoization: recursion must use the memoized name
const fib = memoize(n => (n < 2 ? n : fib(n - 1) + fib(n - 2)));
console.log("fib(40):", fib(40));
